    function [31:0] getByteSize ; 
        input [31:0] data_width ; 
        input [31:0] dev_code ; 
        reg dev_code_fam ; 
        begin
            if ((((((((((((dev_code == "LFD2NX") || (dev_code == "LFCPNX")) || (dev_code == "LFMXO5")) || (dev_code == "UT24C")) || (dev_code == "UT24CP")) || (dev_code == "LIFCL")) || (dev_code == "ap6a400")) || (dev_code == "ap6a00b")) || (dev_code == "ap6a00")) || (dev_code == "LATG1")) || (dev_code == "LAV-AT"))) 
                begin
                    dev_code_fam = 1 ;
                end
            else
                begin
                    dev_code_fam = 0 ;
                end
            case (dev_code_fam)
            1 : 
                begin
                    if (((data_width % 9) == 0)) 
                        getByteSize = 9 ;
                    else
                        getByteSize = 8 ;
                end
            default : 
                getByteSize = 8 ;
            endcase 
        end
    endfunction
    function [31:0] clog2 ; 
        input [31:0] value ; 
        reg [31:0] num ; 
        begin
            num = (value - 1) ;
            for (clog2 = 0 ; (num > 0) ; clog2 = (clog2 + 1))
                num = (num >> 1) ;
        end
    endfunction
    function [31:0] roundUP ; 
        input [31:0] dividend ; 
        input [31:0] divisor ; 
        begin
            if ((divisor == 1)) 
                begin
                    roundUP = dividend ;
                end
            else
                if ((divisor == dividend)) 
                    begin
                        roundUP = 1 ;
                    end
                else
                    begin
                        roundUP = ((dividend / divisor) + (((dividend % divisor) == 0) ? 0 : 1)) ;
                    end
        end
    endfunction
