        parameter FAMILY_CODE = ((FAMILY == "LIFCL") ? _FCODE_LIFCL_ : ((FAMILY == "ap6a400") ? _FCODE_AP6_ : ((FAMILY == "ap6a00b") ? _FCODE_AP6_ : ((FAMILY == "ap6a00") ? _FCODE_AP6_ : ((FAMILY == "LATG1") ? _FCODE_AP6_ : ((FAMILY == "LAV-AT") ? _FCODE_AP6_ : _FCODE_COMMON_)))))), 
