                                    assign in_a_ebr_w = in_a_top_w ; 
                                    assign out_a_top_w = out_a_ebr_w ; 
                                    // ------ PORT B (TOP level to EBR level splt) Wiring : (DATA_WIDTH_B > DATA_WIDTH_A) ------
                                    wire [(A_DWID_IMPL - 1):0] in_b_ebr_seg_w [((PORT_B_DATA_USE / A_DWID_IMPL) - 1):0] ; 
