    localparam TAG_WIDTH = ((LINE_COUNT == 32) ? 15 : ((LINE_COUNT == 16) ? 16 : ((LINE_COUNT == 8) ? 17 : ((LINE_COUNT == 4) ? 18 : 0)))) ; 
