    // bit[15:0] adress tag
    wire [23:0] way0_tag_rd_data ; 
    wire way0_tag_wr_en ; 
    wire [23:0] way1_tag_wr_data ; // bit[17] valid 
    // bit[16] dirty
    // bit[15:0] adress tag
    wire [23:0] way1_tag_rd_data ; 
    wire way1_tag_wr_en ; 
    //AXI Tag Singals
    wire [(TAG_ADDR_WIDTH - 2):0] AXI_tag_addr ; 
    wire [23:0] way0_AXI_tag_wr_data ; // bit[17] valid 
    // bit[16] dirty
    // bit[15:0] adress tag
    wire [23:0] way0_AXI_tag_rd_data ; 
    wire way0_AXI_tag_wr_en ; 
    wire [23:0] way1_AXI_tag_wr_data ; // bit[17] valid 
    // bit[16] dirty
    // bit[15:0] adress tag
    wire [23:0] way1_AXI_tag_rd_data ; 
