    reg [31:0] data_r ; //L1 cache data
    reg wr_cmd_r ; //L1 cache write
    reg [(BYTE_WIDTH - 1):0] mask_r ; //L1 cache mask
    reg [2:0] size_r ; //L1 cache read/write size 
    reg burst_r ; 
    reg ack_done ; //L1 invalidate ack done
    reg line_load ; 
    reg [1:0] line_load_cnt ; 
    reg line_store ; 
    reg [3:0] line_store_cnt ; 
    reg [7:0] wr_cnt ; 
    reg [7:0] rd_cnt ; 
    wire way0_hit ; 
    wire way1_hit ; 
    wire way0_valid ; 
    wire way1_valid ; 
    wire way0_dirty ; 
    wire way1_dirty ; 
