    reg way1_dirty_new ; 
    reg way0_valid_new ; 
    reg way1_valid_new ; 
    reg axi_way0_dirty_new ; 
    reg axi_way1_dirty_new ; 
    reg axi_way0_valid_new ; 
    reg axi_way1_valid_new ; 
    reg [31:0] axi_addr_r ; 
    reg aw_en ; 
    reg [11:0] aw_addr ; 
    reg [11:0] ar_addr ; 
    reg ctr_success ; 
    reg ctr_block_not_found ; 
    reg ctr_block_not_valid ; 
    wire ctr_start ; 
    reg ctr_wb_busy ; 
    reg ctr_flush_busy ; 
    reg ctr_flush_waitfortag ; 
    wire ctr_done ; 
    reg [31:0] ctr_addr ; 
    reg rvalid ; 
    reg [31:0] rdata ; 
    reg bvalid ; 
    reg [31:0] reg_axi1_address ; 
    reg [7:0] reg_axi1_len ; 
    reg reg_axi1_vld ; 
    reg reg_axi1_wr ; 
    reg axi_wb_busy ; //write back cache line to memory
    reg axi_inv_busy ; //invalidate the cache line in system cache
    reg [31:0] inv_address ; 
    reg [7:0] inv_len ; 
    reg [9:0] addr_cnt ; 
