    assign cmd_fire = (dbus_cmd_ready & dbus_cmd_valid) ; 
    assign tag_addr = (cmd_fire ? dbus_cmd_payload_address[(31 - TAG_WIDTH):12] : (cmd_busy ? addr_r[(31 - TAG_WIDTH):12] : ctr_addr[(31 - TAG_WIDTH):12])) ; 
    assign way0_valid = way0_tag_rd_data[TAG_WIDTH] ; 
    assign way1_valid = way1_tag_rd_data[TAG_WIDTH] ; 
    assign way0_dirty = way0_tag_rd_data[(TAG_WIDTH + 1)] ; 
    assign way1_dirty = way1_tag_rd_data[(TAG_WIDTH + 1)] ; 
    assign way0_hit = ((cmd_fire || cmd_busy) ? ((way0_tag_rd_data[(TAG_WIDTH - 1):0] == addr_r[31:(32 - TAG_WIDTH)]) & way0_valid) : (way0_tag_rd_data[(TAG_WIDTH - 1):0] == ctr_addr[31:(32 - TAG_WIDTH)])) ; 
    assign way1_hit = ((cmd_fire || cmd_busy) ? ((way1_tag_rd_data[(TAG_WIDTH - 1):0] == addr_r[31:(32 - TAG_WIDTH)]) & way1_valid) : (way1_tag_rd_data[(TAG_WIDTH - 1):0] == ctr_addr[31:(32 - TAG_WIDTH)])) ; 
    assign way0_tag_wr_data = ((cmd_fire || cmd_busy) ? {{(22 - TAG_ADDR_WIDTH){1'b0}},
                way0_dirty_new,
                way0_valid_new,
                addr_r[31:(32 - TAG_WIDTH)]} : {{(22 - TAG_ADDR_WIDTH){1'b0}},
                way0_dirty_new,
                way0_valid_new,
                ctr_addr[31:(32 - TAG_WIDTH)]}) ; //todo
    assign way1_tag_wr_data = ((cmd_fire || cmd_busy) ? {{(22 - TAG_ADDR_WIDTH){1'b0}},
                way1_dirty_new,
                way1_valid_new,
                addr_r[31:(32 - TAG_WIDTH)]} : {{(22 - TAG_ADDR_WIDTH){1'b0}},
                way1_dirty_new,
