    assign way1_addr_a_i = ($unsigned(addr_r[11:2]) + (burst_r ? $unsigned(addr_offset) : 0)) ; 
    assign way0_addr_a_i = ($unsigned(addr_r[11:2]) + (burst_r ? $unsigned(addr_offset) : 0)) ; 
