    assign way1_wr_en_a_i = ((((wr_cmd_r & cmd_r) & way1_hit) & way1_valid) & (~(line_load | line_store))) ; 
    assign way0_ben_b_i = {BYTE_WIDTH{1'b1}} ; 
    assign way1_ben_b_i = {BYTE_WIDTH{1'b1}} ; 
    assign way0_wr_data_b_i = axi_m_rdata_i ; 
    assign way1_wr_data_b_i = axi_m_rdata_i ; 
    assign way0_wr_en_b_i = (axi_m_rvalid_i & way0_hit) ; 
    assign way1_wr_en_b_i = (axi_m_rvalid_i & way1_hit) ; 
    assign way0_addr_b_i = (line_store ? {(~line_store_cnt),
                (~wr_cnt[5:0])} : {(~line_load_cnt),
                (~rd_cnt)}) ; 
    assign way1_addr_b_i = (line_store ? {(~line_store_cnt),
                (~wr_cnt[5:0])} : {(~line_load_cnt),
                (~rd_cnt)}) ; 
    // To CPU
