                    cmd_r <=  0 ;
                    cmd_id_r <=  {(CPU_COUNT * 2){1'b0}} ;
                end
            else
                if (cmd_fire) 
                    begin
                        cmd_r <=  1 ;
                        cmd_id_r <=  dbus_cmd_id ;
                    end
                else
                    if (((((size_r == 3'd0) & (way0_hit | way1_hit)) & (~(line_load | line_store))) & cmd_r)) 
                        begin
                            cmd_r <=  0 ;
                        end
        end
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    cmd_r_r <=  0 ;
                end
            else
                begin
                    cmd_r_r <=  cmd_r ;
                end
