    assign dbus_rsp_valid = rsp_vld_r ; 
    assign dbus_rsp_payload_data = (way0_hit ? way0_rd_data_a_o[tag_addr_r] : way1_rd_data_a_o[tag_addr_r]) ; 
    assign dbus_rsp_payload_last = rsp_last_r ; 
    assign dbus_rsp_payload_error = err_out ; 
    wire tag_full ; 
    // Line store logic
    reg wb_hit ; 
    always
        @(posedge clk_i or 
            negedge rstn_i)
