                                    ctr_addr[31:24] <=  axi_lite_wdata[31:24] ;
                                end
                            if (axi_lite_wstrb[2]) 
                                begin
                                    ctr_addr[23:16] <=  axi_lite_wdata[23:16] ;
                                end
                            if (axi_lite_wstrb[1]) 
                                begin
                                    ctr_addr[15:8] <=  axi_lite_wdata[15:8] ;
                                end
                            if (axi_lite_wstrb[0]) 
                                begin
                                    ctr_addr[7:0] <=  axi_lite_wdata[7:0] ;
                                end
                        end
                end
        end
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    rvalid <=  0 ;
                    rdata <=  0 ;
                end
            else
                begin
                    if ((axi_lite_arvalid && axi_lite_arready)) 
                        begin
                            rvalid <=  1 ;
                            if ((ar_addr == 12'h0)) 
                                begin
                                    rdata <=  {ctr_done,
                                            ctr_success,
                                            ctr_block_not_found,
                                            ctr_block_not_valid,
                                            27'h0,
                                            1'b0} ;
                                end
                            else
                                if ((ar_addr == 12'h0)) 
                                    begin
                                        rdata <=  ctr_addr ;
                                    end
                                else
                                    begin
                                        rdata <=  32'h0 ;
                                    end
                        end
                    if ((rvalid && axi_lite_rready)) 
                        begin
                            rvalid <=  0 ;
                        end
                end
        end
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    bvalid <=  0 ;
                end
            else
                begin
                    if (((axi_lite_wvalid && axi_lite_wready) && aw_en)) 
                        begin
                            bvalid <=  1 ;
                        end
                    if ((bvalid && axi_lite_bready)) 
                        begin
                            bvalid <=  0 ;
                        end
                end
        end
    assign axi_lite_rvalid = rvalid ; 
    assign axi_lite_rdata = rdata ; 
    assign axi_lite_rresp = 2'b0 ; 
    assign axi_lite_arready = 1'b1 ; 
    assign axi_lite_awready = 1'b1 ; 
    assign axi_lite_wready = 1'b1 ; 
    assign axi_lite_bresp = 2'b0 ; 
    assign axi_lite_bvalid = bvalid ; 
    //control logics for soft write-back and flushing
    assign ctr_start = (ctr_done && (((((axi_lite_wvalid && axi_lite_wready) && aw_en) && (aw_addr == 12'h0)) && axi_lite_wstrb[0]) && axi_lite_wdata[0])) ; 
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    ctr_wb_busy <=  0 ;
                    ctr_success <=  0 ;
                end
            else
                begin
                    if ((ctr_start && axi_lite_wdata[1])) 
                        begin
                            ctr_wb_busy <=  1 ;
                            ctr_success <=  0 ;
                        end
                    else
                        if ((((~cmd_busy) && ctr_wb_busy) && ((~way0_hit) && (~way1_hit)))) 
                            begin
                                ctr_wb_busy <=  0 ;
                                ctr_success <=  0 ;
                            end
                        else
                            if (((axi_m_bvalid_i && (line_store_cnt == 4'b0)) && (ctr_wb_busy == 1))) 
                                begin
                                    ctr_wb_busy <=  0 ;
                                    ctr_success <=  1 ;
                                end
                end
        end
    //reg the flush busy state for 1 clock to read the tag info from tag ram
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    ctr_flush_busy <=  0 ;
                    ctr_flush_waitfortag <=  0 ;
                end
            else
                begin
                    if ((ctr_start && axi_lite_wdata[2])) 
                        begin
                            ctr_flush_busy <=  1 ;
                        end
                    else
                        if ((ctr_flush_busy && (~cmd_busy))) 
                            begin
                                ctr_flush_busy <=  0 ;
                                ctr_flush_waitfortag <=  1 ;
                            end
                        else
                            if (ctr_flush_waitfortag) 
                                begin
                                    ctr_flush_waitfortag <=  0 ;
                                end
                end
        end
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    ctr_block_not_found <=  0 ;
                    ctr_block_not_valid <=  0 ;
                end
            else
                begin
                    if ((ctr_wb_busy && (~cmd_busy))) 
                        begin
                            ctr_block_not_found <=  (~(way0_hit || way1_hit)) ;
                            ctr_block_not_valid <=  (~(way0_valid || way1_valid)) ;
                        end
                end
        end
    assign ctr_done = (~(ctr_wb_busy || ctr_flush_busy)) ; 
    //reg if the AXI channel 0 also issues a transaction at the same time
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    reg_axi1_address <=  0 ;
                    reg_axi1_len <=  0 ;
                    reg_axi1_vld <=  0 ;
                    reg_axi1_wr <=  0 ;
                end
            else
                begin
                    if ((axi_access_valid0 && axi_access_valid1)) 
                        begin
                            reg_axi1_address <=  axi_access_address1 ;
                            reg_axi1_len <=  axi_wr_access_len1 ;
                            reg_axi1_vld <=  1 ;
                            reg_axi1_wr <=  axi_access_wr1 ;
                        end
                    else
                        if (((((reg_axi1_vld && (~axi_access_valid0)) && (~axi_access_valid1)) && (~axi_inv_busy)) && (~axi_wb_busy))) 
                            begin
                                reg_axi1_vld <=  0 ;
                            end
                end
        end
    //cpu cache invalidate logics
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    inv_len <=  0 ;
                    inv_address <=  0 ;
                end
            else
                begin
                    if ((axi_access_valid0 && axi_access_wr0)) 
                        begin
                            inv_address <=  axi_access_address0 ;
                            inv_len <=  axi_wr_access_len0 ;
                        end
                    else
                        if ((axi_access_valid1 && axi_access_wr1)) 
                            begin
                                inv_address <=  axi_access_address1 ;
                                inv_len <=  axi_wr_access_len1 ;
                            end
                        else
                            if ((reg_axi1_vld && reg_axi1_wr)) 
                                begin
                                    inv_address <=  reg_axi1_address ;
                                    inv_len <=  reg_axi1_len ;
                                end
                end
        end
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    addr_cnt <=  0 ;
                end
            else
                begin
                    if (((((axi_access_valid0 && axi_access_wr0) || (axi_access_valid1 && axi_access_wr1)) || (reg_axi1_vld && reg_axi1_wr)) && (~axi_inv_busy))) 
                        begin
                            addr_cnt <=  0 ;
                        end
                    else
                        if ((addr_cnt ^ inv_len)) 
                            begin
                                addr_cnt <=  (addr_cnt + 1) ;
                            end
                end
        end
    assign dbus_inv_id = 0 ; 
    assign dbus_inv_valid = axi_inv_busy ; 
    assign dbus_inv_payload_last = (addr_cnt == inv_len) ; 
    assign dbus_inv_payload_fragment_enable = axi_inv_busy ; 
    assign dbus_inv_payload_fragment_address = (inv_address + (addr_cnt << 2)) ; 
    assign dbus_ack_ready = 1 ; 
    //tag logic for axi 
    assign AXI_tag_addr = (axi_access_valid0 ? axi_access_address0[(31 - TAG_WIDTH):12] : (axi_access_valid1 ? axi_access_address1[(31 - TAG_WIDTH):12] : ((((~axi_inv_busy) && (~axi_wb_busy)) && reg_axi1_vld) ? reg_axi1_address[(31 - TAG_WIDTH):12] : axi_addr_r[(31 - TAG_WIDTH):12]))) ; 
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    axi_addr_r <=  0 ;
                end
            else
                begin
                    if (axi_access_valid0) 
                        begin
                            axi_addr_r <=  axi_access_address0 ;
                        end
                    else
                        if (axi_access_valid1) 
                            begin
                                axi_addr_r <=  axi_access_address1 ;
                            end
                        else
                            if (((reg_axi1_vld && (~axi_inv_busy)) && (~axi_wb_busy))) 
                                begin
                                    axi_addr_r <=  reg_axi1_address ;
                                end
                end
        end
    assign axi_way0_valid = way0_AXI_tag_rd_data[TAG_WIDTH] ; 
    assign axi_way1_valid = way1_AXI_tag_rd_data[TAG_WIDTH] ; 
    assign axi_way0_dirty = way0_AXI_tag_rd_data[(TAG_WIDTH + 1)] ; 
    assign axi_way1_dirty = way1_AXI_tag_rd_data[(TAG_WIDTH + 1)] ; 
    assign axi_way0_hit = ((way0_AXI_tag_rd_data[(TAG_WIDTH - 1):0] == axi_addr_r[31:(32 - TAG_WIDTH)]) & axi_way0_valid) ; 
    assign axi_way1_hit = ((way1_AXI_tag_rd_data[(TAG_WIDTH - 1):0] == axi_addr_r[31:(32 - TAG_WIDTH)]) & axi_way1_valid) ; 
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    axi_inv_busy <=  0 ;
                end
            else
                begin
                    if (((((axi_access_valid0 && axi_access_wr0) || ((~axi_access_valid0) && ((axi_access_valid1 && axi_access_wr1) || (reg_axi1_vld && reg_axi1_wr)))) && (~axi_inv_busy)) && (~axi_wb_busy))) 
                        begin
                            axi_inv_busy <=  1 ;
                        end
                    else
                        if (((axi_inv_busy && dbus_inv_valid) && dbus_inv_payload_last)) 
                            begin
                                axi_inv_busy <=  0 ;
                            end
                end
        end
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    axi0_busy <=  0 ;
                end
            else
                begin
                    if (axi_access_valid0) 
                        begin
                            axi0_busy <=  1 ;
                        end
                    else
                        if (((axi_inv_busy && dbus_inv_valid) && dbus_inv_payload_last)) 
                            begin
                                axi0_busy <=  0 ;
                            end
                        else
                            if (axi_wr_done) 
                                begin
                                    axi0_busy <=  0 ;
                                end
                end
        end
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    axi_wb_busy <=  0 ;
                end
            else
                begin
                    if (((((axi_access_valid0 && (~axi_access_wr0)) || ((~axi_access_valid0) && ((axi_access_valid1 && (~axi_access_wr1)) || (reg_axi1_vld && (~reg_axi1_wr))))) && (~axi_wb_busy)) && (~axi_inv_busy))) 
                        begin
                            axi_wb_busy <=  1 ;
                        end
                    else
                        if (axi_wr_done) 
                            begin
                                axi_wb_busy <=  0 ;
                            end
                end
        end
    reg axi_inv_busy_r ; 
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    axi_inv_busy_r <=  0 ;
                end
            else
                begin
                    axi_inv_busy_r <=  axi_inv_busy ;
                end
        end
