    reg axi_way1_inv_tag_wr_en ; 
    always
        @(posedge clk_i or 
            negedge rstn_i)
        begin
            if ((~rstn_i)) 
                begin
                    axi_way0_valid_new <=  0 ;
                    axi_way1_valid_new <=  0 ;
                    axi_way0_inv_tag_wr_en <=  0 ;
                    axi_way1_inv_tag_wr_en <=  0 ;
