                                axi_way1_valid_new <=  0 ;
                                axi_way1_inv_tag_wr_en <=  1 ;
                            end
                    end
                else
                    begin
                        axi_way0_valid_new <=  axi_way0_valid ;
                        axi_way1_valid_new <=  axi_way1_valid ;
                        axi_way0_inv_tag_wr_en <=  0 ;
                        axi_way1_inv_tag_wr_en <=  0 ;
                    end
        end
    reg axi_way0_wb_tag_wr_en ; 
    reg axi_way1_wb_tag_wr_en ; 
    always
        @(*)
        begin
            axi_way0_dirty_new <=  axi_way0_dirty ;
            axi_way1_dirty_new <=  axi_way1_dirty ;
            axi_way0_wb_tag_wr_en <=  0 ;
            axi_way1_wb_tag_wr_en <=  0 ;
            if (axi_wb_busy) 
                begin
                    if (((axi_way0_valid && axi_way0_hit) && axi_way0_dirty)) 
                        begin
                            axi_way0_dirty_new <=  0 ;
                            axi_way0_wb_tag_wr_en <=  1 ;
                        end
                    if (((axi_way1_valid && axi_way1_hit) && axi_way0_dirty)) 
                        begin
                            axi_way1_dirty_new <=  0 ;
                            axi_way1_wb_tag_wr_en <=  1 ;
                        end
                end
        end
    assign busy = (axi_inv_busy || axi_wb_busy) ; 
    assign axi_port1_pending = reg_axi1_vld ; 
    assign axi_inv_done = ((axi_inv_busy && dbus_inv_valid) && dbus_inv_payload_last) ; //only 1 cycle needed to write to the tag ram
    assign axi_wr_done = (axi_wb_busy && (((axi_m_bvalid_i && (line_store_cnt == 4'b0)) && wb_hit) || ((~(((axi_way0_hit && axi_way0_valid) && axi_way0_dirty) || ((axi_way1_hit && axi_way1_valid) && axi_way1_dirty))) && (~wb_hit)))) ; 
    assign way0_AXI_tag_wr_data = {{(22 - TAG_ADDR_WIDTH){1'b0}},
                axi_way0_dirty_new,
                axi_way0_valid_new,
                axi_addr_r[31:(32 - TAG_WIDTH)]} ; 
    assign way1_AXI_tag_wr_data = {{(22 - TAG_ADDR_WIDTH){1'b0}},
                axi_way1_dirty_new,
                axi_way1_valid_new,
                axi_addr_r[31:(32 - TAG_WIDTH)]} ; 
    assign way0_AXI_tag_wr_en = (axi_way0_inv_tag_wr_en || axi_way0_wb_tag_wr_en) ; 
    assign way1_AXI_tag_wr_en = (axi_way1_inv_tag_wr_en || axi_way1_wb_tag_wr_en) ; 
endmodule



