                                                            if (rst_a_i) 
                                                                begin
                                                                    addr_a_p_r <=  {ADDR_WIDTH_A{1'b0}} ;
                                                                end
                                                            else
                                                                if (clk_en_a_i) 
                                                                    begin
                                                                        addr_a_p_r <=  addr_a_i ;
                                                                    end
                                                        end
                                                end
                                            else
                                                begin : genblk1
                                                    always
                                                        @(posedge clk_a_i or 
                                                            posedge rst_a_i)
                                                        begin
                                                            if (rst_a_i) 
                                                                begin
                                                                    addr_a_p_r <=  {ADDR_WIDTH_A{1'b0}} ;
                                                                end
                                                            else
                                                                if (clk_en_a_i) 
                                                                    begin
                                                                        addr_a_p_r <=  addr_a_i ;
                                                                    end
                                                        end
                                                end
                                        end
                                    else
                                        begin : genblk1
                                            reg [(ADDR_WIDTH_A - 1):0] addr_a_p2_r = {ADDR_WIDTH_A{1'b0}} ; 
                                            if ((RESETMODE_A == "sync")) 
                                                begin : genblk1
                                                    always
                                                        @(posedge clk_a_i)
                                                        begin
                                                            if (rst_a_i) 
                                                                begin
                                                                    addr_a_p2_r <=  {ADDR_WIDTH_A{1'b0}} ;
                                                                    addr_a_p_r <=  {ADDR_WIDTH_A{1'b0}} ;
                                                                end
                                                            else
                                                                if (clk_en_a_i) 
                                                                    begin
                                                                        addr_a_p2_r <=  addr_a_i ;
                                                                        addr_a_p_r <=  addr_a_p2_r ;
                                                                    end
                                                        end
                                                end
                                            else
                                                begin : genblk1
                                                    always
                                                        @(posedge clk_a_i or 
                                                            posedge rst_a_i)
                                                        begin
                                                            if (rst_a_i) 
                                                                begin
                                                                    addr_a_p2_r <=  {ADDR_WIDTH_A{1'b0}} ;
                                                                    addr_a_p_r <=  {ADDR_WIDTH_A{1'b0}} ;
                                                                end
                                                            else
                                                                if (clk_en_a_i) 
                                                                    begin
                                                                        addr_a_p2_r <=  addr_a_i ;
                                                                        addr_a_p_r <=  addr_a_p2_r ;
                                                                    end
                                                        end
                                                end
                                        end
                                    // ------ PORT B output assignment ------
                                    reg [(DATA_WIDTH_B - 1):0] b_out_buff_r = {DATA_WIDTH_B{1'b0}} ; 
                                    reg [(ADDR_WIDTH_B - 1):0] addr_b_p_r = {ADDR_WIDTH_B{1'b0}} ; 
                                    assign out_b_ebr_w = b_out_buff_r ; 
                                    always
                                        @(*)
                                        begin
                                            b_out_buff_r = out_b_ebr_raw_w[addr_b_p_r[(ADDR_WIDTH_B - 1):B_AWID_IMPL]] ;
                                        end
                                    if ((REGMODE_B == "noreg")) 
                                        begin : genblk2
                                            if ((RESETMODE_B == "sync")) 
                                                begin : genblk1
                                                    always
                                                        @(posedge clk_b_i)
                                                        begin
                                                            if (rst_b_i) 
                                                                begin
                                                                    addr_b_p_r <=  {ADDR_WIDTH_B{1'b0}} ;
                                                                end
                                                            else
                                                                if (clk_en_b_i) 
                                                                    begin
                                                                        addr_b_p_r <=  addr_b_i ;
                                                                    end
                                                        end
                                                end
                                            else
                                                begin : genblk1
                                                    always
                                                        @(posedge clk_b_i or 
                                                            posedge rst_b_i)
                                                        begin
                                                            if (rst_b_i) 
                                                                begin
                                                                    addr_b_p_r <=  {ADDR_WIDTH_B{1'b0}} ;
                                                                end
                                                            else
                                                                if (clk_en_b_i) 
                                                                    begin
                                                                        addr_b_p_r <=  addr_b_i ;
                                                                    end
                                                        end
                                                end
                                        end
                                    else
                                        begin : genblk2
                                            reg [(ADDR_WIDTH_B - 1):0] addr_b_p2_r = {ADDR_WIDTH_B{1'b0}} ; 
                                            if ((RESETMODE_B == "sync")) 
                                                begin : genblk1
                                                    always
                                                        @(posedge clk_b_i)
                                                        begin
                                                            if (rst_b_i) 
                                                                begin
                                                                    addr_b_p2_r <=  {ADDR_WIDTH_B{1'b0}} ;
                                                                    addr_b_p_r <=  {ADDR_WIDTH_B{1'b0}} ;
                                                                end
                                                            else
                                                                if (clk_en_b_i) 
                                                                    begin
                                                                        addr_b_p2_r <=  addr_b_i ;
                                                                        addr_b_p_r <=  addr_b_p2_r ;
                                                                    end
                                                        end
                                                end
                                            else
                                                begin : genblk1
                                                    always
                                                        @(posedge clk_b_i or 
                                                            posedge rst_b_i)
                                                        begin
                                                            if (rst_b_i) 
                                                                begin
                                                                    addr_b_p2_r <=  {ADDR_WIDTH_B{1'b0}} ;
                                                                    addr_b_p_r <=  {ADDR_WIDTH_B{1'b0}} ;
                                                                end
                                                            else
                                                                if (clk_en_b_i) 
                                                                    begin
                                                                        addr_b_p2_r <=  addr_b_i ;
                                                                        addr_b_p_r <=  addr_b_p2_r ;
                                                                    end
                                                        end
                                                end
                                        end
                                end
                        end
            end
    endgenerate
