    function [1:0] checkINIT ; 
        input [31:0] val ; 
        begin
            case (val)
            _FCODE_LIFCL_ : 
                checkINIT = 1 ;
            _FCODE_AP6_ : 
                checkINIT = 2 ;
            default : 
                checkINIT = 0 ;
            endcase 
        end
    endfunction
    function [31:0] getImplByteWidth ; 
        input [31:0] dwid ; 
        input [31:0] family_code ; 
        begin
            case (family_code)
            _FCODE_LIFCL_ : 
                begin
                    case (dwid)
                    18 : 
                        getImplByteWidth = 2 ;
                    16 : 
                        getImplByteWidth = 2 ;
                    9 : 
                        getImplByteWidth = 1 ;
                    default : 
                        getImplByteWidth = 1 ;
                    endcase 
                end
            _FCODE_AP6_ : 
                begin
                    case (dwid)
                    36 : 
                        getImplByteWidth = 4 ;
                    32 : 
                        getImplByteWidth = 4 ;
                    18 : 
                        getImplByteWidth = 2 ;
                    16 : 
                        getImplByteWidth = 2 ;
                    9 : 
                        getImplByteWidth = 1 ;
                    default : 
                        getImplByteWidth = 1 ;
                    endcase 
                end
            default : 
                getImplByteWidth = 1 ;
            endcase 
        end
    endfunction
    function [31:0] getDatabase ; 
        input [31:0] base_count ; 
        input [31:0] index ; 
        input [31:0] family_code ; 
        begin
            case (family_code)
            _FCODE_LIFCL_ : 
                begin
                    case (base_count)
                    9 : 
                        begin
                            case (index)
                            0 : 
                                getDatabase = 9 ;
                            default : 
                                getDatabase = 18 ;
                            endcase 
                        end
                    8 : 
                        begin
                            case (index)
                            0 : 
                                getDatabase = 1 ;
                            1 : 
                                getDatabase = 2 ;
                            2 : 
                                getDatabase = 4 ;
                            3 : 
                                getDatabase = 8 ;
                            default : 
                                getDatabase = 16 ;
                            endcase 
                        end
                    default : 
                        getDatabase = 16 ;
                    endcase 
                end
            _FCODE_AP6_ : 
                begin
                    case (base_count)
                    9 : 
                        begin
                            case (index)
                            0 : 
                                getDatabase = 9 ;
                            1 : 
                                getDatabase = 18 ;
                            default : 
                                getDatabase = 36 ;
                            endcase 
                        end
                    8 : 
                        begin
                            case (index)
                            0 : 
                                getDatabase = 1 ;
                            1 : 
                                getDatabase = 2 ;
                            2 : 
                                getDatabase = 4 ;
                            3 : 
                                getDatabase = 8 ;
                            4 : 
                                getDatabase = 16 ;
                            default : 
                                getDatabase = 32 ;
                            endcase 
                        end
                    default : 
                        getDatabase = 16 ;
                    endcase 
                end
            default : 
                getDatabase = base_count ;
            endcase 
        end
    endfunction
    function [31:0] getCASE1DataImpl_wBEN ; 
        input [31:0] addr_a_depth ; 
        input [31:0] data_a_width ; 
        input [31:0] addr_b_depth ; 
        input [31:0] data_b_width ; 
        input is_taking_port_a ; 
        input [31:0] family_code ; 
        reg [31:0] max_width, 
            min_width, 
            byte_size ; 
        reg [31:0] temp_00, 
            temp_01, 
            upper_factor, 
            lower_factor ; 
        reg [31:0] wr_addr_chk, 
            wr_data_chk, 
            rd_addr_chk, 
            rd_data_chk, 
            wr_data_div, 
            rd_data_div ; 
        begin
            case (family_code)
            _FCODE_LIFCL_ : 
                begin
                    if ((data_a_width > data_b_width)) 
                        begin
                            if (is_taking_port_a) 
                                begin
                                    if (((data_a_width % 9) == 0)) 
                                        getCASE1DataImpl_wBEN = 18 ;
                                    else
                                        getCASE1DataImpl_wBEN = 16 ;
                                end
                            else
                                begin
                                    if (((data_a_width % 9) == 0)) 
                                        getCASE1DataImpl_wBEN = 9 ;
                                    else
                                        getCASE1DataImpl_wBEN = 8 ;
                                end
                        end
                    else
                        begin
                            if (is_taking_port_a) 
                                begin
                                    if (((data_a_width % 9) == 0)) 
                                        getCASE1DataImpl_wBEN = 9 ;
                                    else
                                        getCASE1DataImpl_wBEN = 8 ;
                                end
                            else
                                begin
                                    if (((data_a_width % 9) == 0)) 
                                        getCASE1DataImpl_wBEN = 18 ;
                                    else
                                        getCASE1DataImpl_wBEN = 16 ;
                                end
                        end
                end
            _FCODE_AP6_ : 
                begin
                    max_width = ((data_a_width > data_b_width) ? data_a_width : data_b_width) ;
                    min_width = ((data_a_width < data_b_width) ? data_a_width : data_b_width) ;
                    byte_size = (((max_width % 9) == 0) ? 9 : 8) ;
                    if (((max_width / min_width) == 4)) 
                        begin
                            if ((data_a_width > data_b_width)) 
                                begin
                                    if ((is_taking_port_a == 1)) 
                                        getCASE1DataImpl_wBEN = (4 * byte_size) ;
                                    else
                                        getCASE1DataImpl_wBEN = byte_size ;
                                end
                            else
                                begin
                                    if ((is_taking_port_a == 1)) 
                                        getCASE1DataImpl_wBEN = byte_size ;
                                    else
                                        getCASE1DataImpl_wBEN = (4 * byte_size) ;
                                end
                        end
                    else
                        begin
                            if ((data_a_width > data_b_width)) 
                                begin
                                    wr_addr_chk = roundUP(addr_a_depth,
                                            data_to_addr(36,
                                                family_code)) ;
                                    wr_data_div = ((byte_size == 9) ? 36 : 32) ;
                                    wr_data_chk = roundUP(data_a_width,
                                            wr_data_div) ;
                                    rd_addr_chk = roundUP(addr_b_depth,
                                            data_to_addr(18,
                                                family_code)) ;
                                    rd_data_div = ((byte_size == 9) ? 18 : 16) ;
                                    rd_data_chk = roundUP(data_b_width,
                                            rd_data_div) ;
                                    if (((((wr_addr_chk == rd_addr_chk) && (wr_data_chk == rd_data_chk)) && ((data_a_width % wr_data_div) == 0)) && ((data_b_width % rd_data_div) == 0))) 
                                        temp_00 = (wr_addr_chk * wr_data_chk) ;
                                    else
                                        temp_00 = 32'hffffffff ;
                                    wr_addr_chk = roundUP(addr_a_depth,
                                            data_to_addr(18,
                                                family_code)) ;
                                    wr_data_div = ((byte_size == 9) ? 18 : 16) ;
                                    wr_data_chk = roundUP(data_a_width,
                                            wr_data_div) ;
                                    rd_addr_chk = roundUP(addr_b_depth,
                                            data_to_addr(9,
                                                family_code)) ;
                                    rd_data_div = ((byte_size == 9) ? 9 : 8) ;
                                    rd_data_chk = roundUP(data_b_width,
                                            rd_data_div) ;
                                    if (((((wr_addr_chk == rd_addr_chk) && (wr_data_chk == rd_data_chk)) && ((data_a_width % wr_data_div) == 0)) && ((data_b_width % rd_data_div) == 0))) 
                                        temp_01 = (wr_addr_chk * wr_data_chk) ;
                                    else
                                        temp_01 = 32'hffffffff ;
                                    if ((temp_00 < temp_01)) 
                                        begin
                                            if ((is_taking_port_a == 1)) 
                                                getCASE1DataImpl_wBEN = (4 * byte_size) ;
                                            else
                                                getCASE1DataImpl_wBEN = (2 * byte_size) ;
                                        end
                                    else
                                        begin
                                            if ((is_taking_port_a == 1)) 
                                                getCASE1DataImpl_wBEN = (2 * byte_size) ;
                                            else
                                                getCASE1DataImpl_wBEN = byte_size ;
                                        end
                                end
                            else
                                begin
                                    wr_addr_chk = roundUP(addr_a_depth,
                                            data_to_addr(18,
                                                family_code)) ;
                                    wr_data_div = ((byte_size == 9) ? 18 : 16) ;
                                    wr_data_chk = roundUP(data_a_width,
                                            wr_data_div) ;
                                    rd_addr_chk = roundUP(addr_b_depth,
                                            data_to_addr(36,
                                                family_code)) ;
                                    rd_data_div = ((byte_size == 9) ? 36 : 32) ;
                                    rd_data_chk = roundUP(data_b_width,
                                            rd_data_div) ;
                                    if (((((wr_addr_chk == rd_addr_chk) && (wr_data_chk == rd_data_chk)) && ((data_a_width % wr_data_div) == 0)) && ((data_b_width % rd_data_div) == 0))) 
                                        temp_00 = (wr_addr_chk * wr_data_chk) ;
                                    else
                                        temp_00 = 32'hffffffff ;
                                    wr_addr_chk = roundUP(addr_a_depth,
                                            data_to_addr(9,
                                                family_code)) ;
                                    wr_data_div = ((byte_size == 9) ? 9 : 8) ;
                                    wr_data_chk = roundUP(data_a_width,
                                            wr_data_div) ;
                                    rd_addr_chk = roundUP(addr_b_depth,
                                            data_to_addr(18,
                                                family_code)) ;
                                    rd_data_div = ((byte_size == 9) ? 18 : 16) ;
                                    rd_data_chk = roundUP(data_b_width,
                                            rd_data_div) ;
                                    if (((((wr_addr_chk == rd_addr_chk) && (wr_data_chk == rd_data_chk)) && ((data_a_width % wr_data_div) == 0)) && ((data_b_width % rd_data_div) == 0))) 
                                        temp_01 = (wr_addr_chk * wr_data_chk) ;
                                    else
                                        temp_01 = 32'hffffffff ;
                                    if ((temp_00 < temp_01)) 
                                        begin
                                            if ((is_taking_port_a == 1)) 
                                                getCASE1DataImpl_wBEN = (2 * byte_size) ;
                                            else
                                                getCASE1DataImpl_wBEN = (4 * byte_size) ;
                                        end
                                    else
                                        begin
                                            if ((is_taking_port_a == 1)) 
                                                getCASE1DataImpl_wBEN = byte_size ;
                                            else
                                                getCASE1DataImpl_wBEN = (2 * byte_size) ;
                                        end
                                end
                        end
                end
            default : 
                getCASE1DataImpl_wBEN = 8 ;
            endcase 
        end
    endfunction
    function [31:0] getCASE1DataImpl ; 
        input [31:0] addr_a_depth ; 
        input [31:0] data_a_width ; 
        input [31:0] addr_b_depth ; 
        input [31:0] data_b_width ; 
        input is_taking_port_a ; 
        input is_taking_total_ebr ; 
        input [31:0] family_code ; 
        reg [5:0] num0, 
            num1, 
            limit ; 
        reg [31:0] divisor, 
            addr_div_prtA, 
            data_div_prtA, 
            addr_div_prtB, 
            data_div_prtB ; 
        reg [31:0] portA_addr_chk, 
            portA_data_chk, 
            portB_addr_chk, 
            portB_data_chk ; 
        reg [31:0] EBR_usage, 
            PROD ; 
        begin
            divisor = ((addr_a_depth > addr_b_depth) ? (addr_a_depth / addr_b_depth) : (addr_b_depth / addr_a_depth)) ;
            EBR_usage = {32{1'b1}} ;
            getCASE1DataImpl = 0 ;
            if ((((family_code == _FCODE_LIFCL_) && (divisor <= 2)) || ((family_code == _FCODE_AP6_) && (divisor <= 4)))) 
                begin
                    limit = ((family_code == _FCODE_LIFCL_) ? 2 : 3) ;
                    for (num0 = 0 ; (num0 < limit) ; num0 = (num0 + 1))
                        begin
                            data_div_prtA = getDatabase(9,
                                    num0,
                                    family_code) ;
                            addr_div_prtA = data_to_addr(data_div_prtA,
                                    family_code) ;
                            portA_addr_chk = roundUP(addr_a_depth,
                                    addr_div_prtA) ;
                            portA_data_chk = roundUP(data_a_width,
                                    data_div_prtA) ;
                            for (num1 = 0 ; (num1 < limit) ; num1 = (num1 + 1))
                                begin
                                    data_div_prtB = getDatabase(9,
                                            num1,
                                            family_code) ;
                                    addr_div_prtB = data_to_addr(data_div_prtB,
                                            family_code) ;
                                    portB_addr_chk = roundUP(addr_b_depth,
                                            addr_div_prtB) ;
                                    portB_data_chk = roundUP(data_b_width,
                                            data_div_prtB) ;
                                    if (((portA_addr_chk == portB_addr_chk) && (portA_data_chk == portB_data_chk))) 
                                        begin
                                            if ((((data_a_width % data_div_prtA) == 0) && ((data_b_width % data_div_prtB) == 0))) 
                                                begin
                                                    PROD = (portA_addr_chk * portA_data_chk) ;
                                                    if ((PROD < EBR_usage)) 
                                                        begin
                                                            EBR_usage = PROD ;
                                                            if ((is_taking_total_ebr == 1'b1)) 
                                                                getCASE1DataImpl = EBR_usage ;
                                                            else
                                                                if ((is_taking_port_a == 1'b1)) 
                                                                    getCASE1DataImpl = data_div_prtA ;
                                                                else
                                                                    getCASE1DataImpl = data_div_prtB ;
                                                        end
                                                end
                                        end
                                end
                        end
                end
            limit = ((family_code == _FCODE_LIFCL_) ? 5 : 6) ;
            for (num0 = 0 ; (num0 < limit) ; num0 = (num0 + 1))
                begin
                    data_div_prtA = getDatabase(8,
                            num0,
                            family_code) ;
                    addr_div_prtA = data_to_addr(data_div_prtA,
                            family_code) ;
                    portA_addr_chk = roundUP(addr_a_depth,
                            addr_div_prtA) ;
                    portA_data_chk = roundUP(data_a_width,
                            data_div_prtA) ;
                    for (num1 = 0 ; (num1 < limit) ; num1 = (num1 + 1))
                        begin
                            data_div_prtB = getDatabase(8,
                                    num1,
                                    family_code) ;
                            addr_div_prtB = data_to_addr(data_div_prtB,
                                    family_code) ;
                            portB_addr_chk = roundUP(addr_b_depth,
                                    addr_div_prtB) ;
                            portB_data_chk = roundUP(data_b_width,
                                    data_div_prtB) ;
                            if (((portA_addr_chk == portB_addr_chk) && (portA_data_chk == portB_data_chk))) 
                                begin
                                    if ((((data_a_width % data_div_prtA) == 0) && ((data_b_width % data_div_prtB) == 0))) 
                                        begin
                                            PROD = (portA_addr_chk * portA_data_chk) ;
                                            if ((PROD < EBR_usage)) 
                                                begin
                                                    EBR_usage = PROD ;
                                                    if ((is_taking_total_ebr == 1'b1)) 
                                                        getCASE1DataImpl = EBR_usage ;
                                                    else
                                                        if ((is_taking_port_a == 1'b1)) 
                                                            getCASE1DataImpl = data_div_prtA ;
                                                        else
                                                            getCASE1DataImpl = data_div_prtB ;
                                                end
                                        end
                                end
                        end
                end
        end
    endfunction
    function [31:0] procData ; 
        input [31:0] max_data ; 
        input [31:0] family_code ; 
        begin
            procData = 1 ;
            while ((procData < max_data))
                begin
                    case (family_code)
                    _FCODE_LIFCL_,
                            _FCODE_AP6_ : 
                        begin
                            if ((procData < 8)) 
                                begin
                                    procData = (procData * 2) ;
                                end
                            else
                                begin
                                    if ((procData == 8)) 
                                        begin
                                            procData = 9 ;
                                        end
                                    else
                                        if (((procData % 9) == 0)) 
                                            begin
                                                procData = ((procData / 9) * 16) ;
                                            end
                                        else
                                            begin
                                                procData = ((procData / 8) * 9) ;
                                            end
                                end
                        end
                    default : 
                        procData = max_data ;
                    endcase 
                end
        end
    endfunction
    function [31:0] data_to_addr ; 
        input [31:0] data_size ; 
        input [31:0] family_code ; 
        begin
            case (family_code)
            _FCODE_LIFCL_ : 
                begin
                    case (data_size)
                    18 : 
                        data_to_addr = 1024 ;
                    16 : 
                        data_to_addr = 1024 ;
                    9 : 
                        data_to_addr = 2048 ;
                    8 : 
                        data_to_addr = 2048 ;
                    4 : 
                        data_to_addr = 4096 ;
                    2 : 
                        data_to_addr = 8192 ;
                    default : 
                        data_to_addr = 16384 ;
                    endcase 
                end
            _FCODE_AP6_ : 
                begin
                    case (data_size)
                    36 : 
                        data_to_addr = 1024 ;
                    32 : 
                        data_to_addr = 1024 ;
                    18 : 
                        data_to_addr = 2048 ;
                    16 : 
                        data_to_addr = 2048 ;
                    9 : 
                        data_to_addr = 4096 ;
                    8 : 
                        data_to_addr = 4096 ;
                    4 : 
                        data_to_addr = 8192 ;
                    2 : 
                        data_to_addr = 16384 ;
                    default : 
                        data_to_addr = 32768 ;
                    endcase 
                end
            default : 
                data_to_addr = 1024 ;
            endcase 
        end
    endfunction
    function [31:0] getMinimaData ; 
        input [31:0] depth_impl ; 
        input [31:0] width_impl ; 
        input is_byte_en ; 
        input [31:0] byte_size ; 
        input [31:0] family_code ; 
        reg [31:0] temp_00, 
            temp_01, 
            temp_02, 
            temp_03, 
            temp_04, 
            temp_05 ; 
        begin
            case (family_code)
            _FCODE_LIFCL_ : 
                begin
                    temp_00 = EBR_impl(depth_impl,
                            width_impl,
                            1024,
                            18) ;
                    temp_01 = EBR_impl(depth_impl,
                            width_impl,
                            2048,
                            9) ;
                    temp_02 = EBR_impl(depth_impl,
                            width_impl,
                            4096,
                            4) ;
                    temp_03 = EBR_impl(depth_impl,
                            width_impl,
                            8192,
                            2) ;
                    temp_04 = EBR_impl(depth_impl,
                            width_impl,
                            16384,
                            1) ;
                    if (((is_byte_en == 1) && ((width_impl % 9) != 0))) 
                        begin
                            temp_00 = EBR_impl(depth_impl,
                                    width_impl,
                                    1024,
                                    16) ;
                            temp_01 = EBR_impl(depth_impl,
                                    width_impl,
                                    2048,
